package com.lolfm.composition;
import java.util.*;
public record CapabilityCoverage(CompositionCapability capability,CompositionAggregationType aggregationType,double coverage,List<CapabilityContributor> contributors){public CapabilityCoverage{Objects.requireNonNull(capability);Objects.requireNonNull(aggregationType);contributors=List.copyOf(contributors);if(coverage<0||coverage>1||!Double.isFinite(coverage))throw new IllegalArgumentException();double sum=contributors.stream().mapToDouble(CapabilityContributor::weightedContribution).sum();if(Math.abs(sum-coverage)>1e-12)throw new IllegalArgumentException("Contributor arithmetic mismatch");for(int i=0;i<contributors.size();i++)if(contributors.get(i).rank()!=i+1)throw new IllegalArgumentException("Rank order required");coverage=coverage==0?0.0:coverage;}}
